"""Research-only bridge with documented Praat filtered-AC settings, not a product patch."""
import hashlib,json,pathlib,subprocess,sys
root=pathlib.Path(sys.argv[1]).resolve();repo=pathlib.Path(__file__).resolve().parents[2];out=repo/'outputs/pitch-benchmark/stock-stream-build';out.mkdir(parents=True,exist_ok=True);cached=root/'wasm/build-release';m=json.loads((cached/'manifest.json').read_text());version=subprocess.check_output(['emcc','--version'],text=True).splitlines()[0];assert version==m['toolchain'];src=(root/'wasm/spectrogram.cpp').read_text();old='Sound_to_Pitch_filteredAc(sound.get(),.01,pitchFloor,pitchCeiling,15,false,.03,.03,.45,.01,.35,.14)';new='Sound_to_Pitch_filteredAc(sound.get(),.01,pitchFloor,pitchCeiling,15,false,.03,.09,.50,.055,.35,.14)';assert src.count(old)==1;src=src.replace(old,new);source=out/'research.cpp';source.write_text(src);headers=[p for p in root.rglob('*.h') if '.git' not in p.parts and not any(s.startswith('build') for s in p.parts)];includes=[s for folder in sorted({str(p.parent) for p in headers}) for s in ['-I',folder]];flags=['-O3','-flto','-sUSE_ZLIB=1','-DUNIX','-Dlinux','-DNO_GRAPHICS','-D_FILE_OFFSET_BITS=64','-DWORDS_BIGENDIAN=0','-DPA_LITTLE_ENDIAN','-fexceptions','-std=c++17'];obj=out/'research.o';subprocess.run(['em++',*flags,*includes,'-c',str(source),'-o',str(obj)],check=True);objects=[cached/(n.replace('/','_')+'.o') for n in (root/'wasm/sources.txt').read_text().splitlines()];assert all(p.is_file() for p in objects);subprocess.run(['em++',*[str(p) for p in objects],str(obj),*m['linkFlags'],'-o',str(out/'praat-spectrogram.js')],check=True);h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();(out/'manifest.json').write_text(json.dumps(dict(toolchain=version,bridgeSha256=h(source),cachedManifest=m,assets={n:h(out/n) for n in ['praat-spectrogram.js','praat-spectrogram.wasm']},note='Stock filtered scoring settings;10ms step instead of automatic15ms;50–800Hz; bounded streaming context'),indent=2))
